class DynamicArray:
    """A growable array over a fixed backing store."""

    def __init__(self, capacity=1):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self.writes = 0
        self.resizes = 0
        self._size = 0
        self._store = [None] * capacity

    def __len__(self):
        return self._size

    def _slot(self, index):
        if index < 0:
            index += self._size
        if index < 0 or index >= self._size:
            raise IndexError("index out of range")
        return index

    def __getitem__(self, index):
        return self._store[self._slot(index)]

    def __setitem__(self, index, value):
        self._store[self._slot(index)] = value
        self.writes += 1

    def _resize(self, capacity):
        store = [None] * capacity
        for i in range(self._size):
            store[i] = self._store[i]
            self.writes += 1
        self._store = store
        self.capacity = capacity
        self.resizes += 1

    def append(self, value):
        """Add to the end, doubling the capacity when the store is full."""
        if self._size == self.capacity:
            self._resize(self.capacity * 2)
        self._store[self._size] = value
        self.writes += 1
        self._size += 1

    def pop(self):
        """Remove and return the last value; halve the capacity at a quarter full."""
        if self._size == 0:
            raise IndexError("pop from an empty array")
        value = self._store[self._size - 1]
        self._store[self._size - 1] = None
        self._size -= 1
        if self.capacity > 1 and self._size * 4 <= self.capacity:
            self._resize(max(1, self.capacity // 2))
        return value

    def insert(self, index, value):
        """Shift the tail up and drop value in at index."""
        if index < 0:
            index += self._size
        if index < 0 or index > self._size:
            raise IndexError("index out of range")
        if self._size == self.capacity:
            self._resize(self.capacity * 2)
        for i in range(self._size, index, -1):
            self._store[i] = self._store[i - 1]
            self.writes += 1
        self._store[index] = value
        self.writes += 1
        self._size += 1

    def to_list(self):
        """The live elements as a plain list."""
        return [self._store[i] for i in range(self._size)]


class ListNode:
    """One cell of a singly linked list."""

    def __init__(self, value, next=None):
        self.value = value
        self.next = next


class SinglyLinkedList:
    """A singly linked list with a tail pointer and a traversal counter."""

    def __init__(self, values=None):
        self.head = None
        self.tail = None
        self.steps = 0
        self._size = 0
        for value in values or []:
            self.push_back(value)

    def __len__(self):
        return self._size

    def __iter__(self):
        node = self.head
        while node is not None:
            yield node.value
            node = node.next

    def push_front(self, value):
        """O(1) insertion at the head."""
        self.head = ListNode(value, self.head)
        if self.tail is None:
            self.tail = self.head
        self._size += 1

    def push_back(self, value):
        """O(1) insertion at the tail — no walking."""
        node = ListNode(value)
        if self.tail is None:
            self.head = node
            self.tail = node
        else:
            self.tail.next = node
            self.tail = node
        self._size += 1

    def pop_front(self):
        """Remove and return the head value."""
        if self.head is None:
            raise IndexError("pop from an empty list")
        node = self.head
        self.head = node.next
        if self.head is None:
            self.tail = None
        self._size -= 1
        return node.value

    def find(self, value):
        """Index of the first match, or -1. One step per node examined."""
        node = self.head
        index = 0
        while node is not None:
            self.steps += 1
            if node.value == value:
                return index
            node = node.next
            index += 1
        return -1

    def reverse(self):
        """Reverse in place, fixing head and tail."""
        previous = None
        node = self.head
        self.tail = self.head
        while node is not None:
            self.steps += 1
            following = node.next
            node.next = previous
            previous = node
            node = following
        self.head = previous

    def to_list(self):
        """The values as a plain list."""
        return list(self)


