class TreeNode:
    """One node of a binary search tree."""

    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None


class BST:
    """An unbalanced binary search tree over unique, comparable keys."""

    def __init__(self, keys=None):
        self.root = None
        self._size = 0
        for key in keys or []:
            self.insert(key)

    def __len__(self):
        return self._size

    def insert(self, key):
        """Add a key. True when it was new, False when it was already present."""
        if self.root is None:
            self.root = TreeNode(key)
            self._size += 1
            return True
        node = self.root
        while True:
            if key == node.key:
                return False
            if key < node.key:
                if node.left is None:
                    node.left = TreeNode(key)
                    self._size += 1
                    return True
                node = node.left
            else:
                if node.right is None:
                    node.right = TreeNode(key)
                    self._size += 1
                    return True
                node = node.right

    def contains(self, key):
        """Is the key in the tree?"""
        node = self.root
        while node is not None:
            if key == node.key:
                return True
            node = node.left if key < node.key else node.right
        return False

    def in_order(self):
        """Keys in sorted order."""
        keys = []

        def walk(node):
            if node is None:
                return
            walk(node.left)
            keys.append(node.key)
            walk(node.right)

        walk(self.root)
        return keys

    def pre_order(self):
        """Node, then left subtree, then right subtree."""
        keys = []

        def walk(node):
            if node is None:
                return
            keys.append(node.key)
            walk(node.left)
            walk(node.right)

        walk(self.root)
        return keys

    def post_order(self):
        """Both subtrees, then the node."""
        keys = []

        def walk(node):
            if node is None:
                return
            walk(node.left)
            walk(node.right)
            keys.append(node.key)

        walk(self.root)
        return keys

    def height(self):
        """Edges on the longest root-to-leaf path; -1 for an empty tree."""

        def measure(node):
            if node is None:
                return -1
            return 1 + max(measure(node.left), measure(node.right))

        return measure(self.root)

    def min_key(self):
        """The smallest key; ValueError when empty."""
        if self.root is None:
            raise ValueError("an empty tree has no smallest key")
        node = self.root
        while node.left is not None:
            node = node.left
        return node.key

    def max_key(self):
        """The largest key; ValueError when empty."""
        if self.root is None:
            raise ValueError("an empty tree has no largest key")
        node = self.root
        while node.right is not None:
            node = node.right
        return node.key

    def delete(self, key):
        """Remove a key. True when something went, False when it was absent."""
        if not self.contains(key):
            return False
        self.root = self._delete(self.root, key)
        self._size -= 1
        return True

    def _delete(self, node, key):
        """Remove key from this subtree and return the subtree's new root."""
        if node is None:
            return None
        if key < node.key:
            node.left = self._delete(node.left, key)
        elif key > node.key:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            if node.right is None:
                return node.left
            successor = node.right
            while successor.left is not None:
                successor = successor.left
            node.key = successor.key
            node.right = self._delete(node.right, successor.key)
        return node


